  };
  var STAGE = { 戒备: '--c-stage-hostile', 陌生: '--c-stage-stranger', 熟悉: '--c-stage-familiar', 恋慕: '--c-stage-love', 不渝: '--c-stage-devoted' };
  var MIN = -100, MAX = 1000, TICKS = [[0, '陌生'], [350, '熟悉'], [700, '恋慕'], [900, '不渝']];
  var BASE = window.RT_IMG_BASE || 'https://testingcf.jsdelivr.net/gh/TakaoTay/art@main/';
  var showOthers = false, lastKey = '';

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function stageOf(v) { return v < 0 ? '戒备' : v < 350 ? '陌生' : v < 700 ? '熟悉' : v < 900 ? '恋慕' : '不渝'; }
  function pct(v) { return Math.max(0, Math.min(100, (v - MIN) / (MAX - MIN) * 100)); }
  function canRead() { return typeof getCurrentMessageId === 'function' && typeof getVariables === 'function'; }

  function npcsAt(id) {
    try { var v = getVariables({ type: 'message', message_id: id }); return (v && v.stat_data && v.stat_data.近期NPC) || null; } catch (e) { return null; }
  }
  function readNow() {
    if (!canRead()) return window.__BOND_DEMO__ || { npcs: {}, prev: {}, scene: [] };
    var id = getCurrentMessageId(), npcs = npcsAt(id) || {}, prev = {};
    for (var i = id - 1; i >= 0; i--) { var p = npcsAt(i); if (p) { prev = p; break; } }
    var text = '';
    try { text = (getChatMessages(id)[0] || {}).message || ''; } catch (e) {}
    return { npcs: npcs, prev: prev, scene: sceneNames(text) };
  }
  function sceneNames(text) {
    var names = [], m;
    var si = text.match(/<SceneInfo>([\s\S]*?)<\/SceneInfo>/);
    if (si) si[1].split('\n').forEach(function (l) { var k = l.match(/^\s*-\s*([^|｜]+)/); if (k) names.push(k[1].trim()); });
    var sc = text.match(/出场人物\s*[:：]\s*(.+)/);
    if (sc) sc[1].split(/[、,，\s]+/).forEach(function (n) { if (n) names.push(n.trim()); });
    var seen = {};
    return names.filter(function (n) { return n && !seen[n] && (seen[n] = 1); });
  }

  function row(name, npc, prevNpc, i) {
    var meta = CAST[name] || [null, '#94a3b8'];
    var known = npc && isFinite(Number(npc.好感度));
    var v = known ? Number(npc.好感度) : 100;
    var stage = known ? (npc._关系阶段 || stageOf(v)) : '陌生';
    var delta = known && prevNpc && isFinite(Number(prevNpc.好感度)) ? v - Number(prevNpc.好感度) : 0;
    var img = meta[0] ? BASE + meta[0] + '_rc_q.png' : '';
    if (img && window.rtArt) img = window.rtArt(img);
    var ticks = TICKS.map(function (t) { return '<div class="tick" style="left:' + pct(t[0]) + '%"><span>' + t[1] + '</span></div>'; }).join('');
    return '<div class="bond-row" style="--accent:' + meta[1] + ';--stage:var(' + STAGE[stage] + ');animation-delay:' + (i * 0.07) + 's">' +
      '<div class="avatar">' + esc(name.slice(0, 1)) + (img ? '<img src="' + esc(img) + '" onerror="this.remove()" loading="lazy">' : '') + '</div>' +
      '<div class="info"><div class="line1"><span class="name">' + esc(name) + '</span><span class="stage">' + esc(stage) + '</span>' +
      (delta ? '<span class="delta ' + (delta > 0 ? 'up' : 'down') + '">' + (delta > 0 ? '+' : '') + delta + '</span>' : '') +
      '<span class="value">' + (known ? '<b>' + v + '</b> / ' + MAX : '初遇') + '</span></div>' +
      '<div class="track">' + ticks + '<div class="fill' + (v < 0 ? ' neg' : '') + '" data-w="' + pct(v) + '"></div></div>' +
      (npc && npc.与主角关系 ? '<div class="note"><i>与你</i>' + esc(npc.与主角关系) + '</div>' : '') +
      '</div></div>';
  }

  function render() {
    var d;
    try { d = readNow(); } catch (e) { d = { npcs: {}, prev: {}, scene: [] }; }
    var key = JSON.stringify(d);
    if (key === lastKey) return;
    lastKey = key;
    var npcs = d.npcs || {}, names = Object.keys(npcs);
    var focus = d.scene.filter(function (n) { return npcs[n] || CAST[n]; });
    if (!focus.length) focus = names.slice().sort(function (a, b) { return Number(npcs[b].好感度) - Number(npcs[a].好感度); }).slice(0, 3);
    var others = names.filter(function (n) { return focus.indexOf(n) === -1; })
      .sort(function (a, b) { return Number(npcs[b].好感度) - Number(npcs[a].好感度); });
    var html = '<div class="bond-head"><div class="bond-title">羁 绊<small>BONDS</small></div><div class="bond-tape"></div></div>';
    if (!focus.length) html += '<div class="empty">还没有结识任何人。</div>';
