  --c-surface-sunken: #0c0f16;
  --c-border: #2c3447;
  --c-border-accent: #8a6d3b;
  --c-text: #e6e1d3;
  --c-text-muted: #9aa3b5;
  --c-accent: #c8a45a;
  --c-accent-soft: rgba(200, 164, 90, 0.14);
  --c-hextech: #3fc1c9;
  --c-hextech-soft: rgba(63, 193, 201, 0.14);
  --c-dream: #a58ad6;
  --c-danger: #d0545b;
}
* { box-sizing: border-box; }
body { margin: 0; padding: 4px 0; background: transparent; color: var(--c-text);
  font-family: "Sarasa Gothic SC", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; line-height: 1.55; }
.form { background: var(--c-surface); border: 1px solid var(--c-border); border-radius: 10px; overflow: hidden; }
.form-head { padding: 14px 16px 10px; border-bottom: 1px solid var(--c-border-accent);
  background: linear-gradient(90deg, var(--c-accent-soft), transparent 70%); }
.form-head h2 { margin: 0; font-size: 17px; color: var(--c-accent); letter-spacing: 2px; }
.form-head p { margin: 4px 0 0; color: var(--c-text-muted); font-size: 12px; }
.sec { padding: 12px 16px; border-bottom: 1px solid var(--c-border); }
.sec-title { color: var(--c-accent); font-size: 12px; letter-spacing: 1px; margin-bottom: 8px; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px 12px; }
label { display: block; font-size: 12px; color: var(--c-text-muted); }
label .req { color: var(--c-danger); }
input, select, textarea { width: 100%; margin-top: 3px; padding: 6px 8px; border-radius: 6px; border: 1px solid var(--c-border);
  background: var(--c-surface-sunken); color: var(--c-text); font: inherit; font-size: 13px; }
textarea { resize: vertical; min-height: 54px; }
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--c-hextech); }
.full { grid-column: 1 / -1; }
.hint { font-size: 11px; color: var(--c-text-muted); margin-top: 3px; }
.tiers { display: grid; grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 6px; }
.tier { padding: 7px 8px; border-radius: 6px; border: 1px solid var(--c-border); background: var(--c-surface-raised); cursor: pointer; }
.tier b { display: block; font-size: 12px; }
.tier small { color: var(--c-text-muted); font-size: 11px; }
.tier.on { border-color: var(--c-accent); background: var(--c-accent-soft); }
.rel { display: grid; grid-template-columns: 1.1fr 0.9fr 2fr auto; gap: 6px; align-items: end; margin-bottom: 6px; }
.rel input, .rel select { margin-top: 0; }
@media (max-width: 480px) { .rel { grid-template-columns: 1fr 1fr; } .rel .rel-desc { grid-column: 1 / -1; } }
.btn { padding: 6px 12px; border-radius: 6px; border: 1px solid var(--c-border); background: var(--c-surface-raised);
  color: var(--c-text); font: inherit; font-size: 12px; cursor: pointer; }
.btn:hover { border-color: var(--c-hextech); background: var(--c-hextech-soft); }
.btn-x { padding: 6px 9px; color: var(--c-text-muted); }
.chips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }
.chip { font-size: 11px; padding: 3px 8px; border-radius: 10px; border: 1px solid var(--c-border); background: var(--c-surface-raised);
  color: var(--c-text-muted); cursor: pointer; }
.chip:hover { color: var(--c-text); border-color: var(--c-accent); }
.dream { display: flex; gap: 10px; align-items: flex-start; }
.switch { position: relative; flex: 0 0 40px; height: 22px; border-radius: 11px; background: var(--c-border); cursor: pointer; margin-top: 2px; transition: background .2s; }
.switch::after { content: ''; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: var(--c-text); transition: left .2s; }
.switch.on { background: var(--c-dream); }
.switch.on::after { left: 21px; }
.dream-body b { color: var(--c-dream); }
.dream-body p { margin: 2px 0 0; font-size: 12px; color: var(--c-text-muted); }
#dream-extra { display: none; margin-top: 8px; }
#dream-extra.on { display: block; }
.foot { padding: 12px 16px; display: flex; align-items: center; gap: 12px; justify-content: flex-end; background: var(--c-surface-sunken); }
.msg { flex: 1; font-size: 12px; color: var(--c-danger); }
.msg.ok { color: var(--c-hextech); }
.go { padding: 8px 18px; border-radius: 6px; border: 1px solid var(--c-accent); background: var(--c-accent-soft); color: var(--c-accent);
  font: inherit; font-weight: 700; letter-spacing: 2px; cursor: pointer; }
.go:hover { background: var(--c-accent); color: var(--c-surface); }
.go:disabled { opacity: .5; cursor: default; }
</style>

<div class="form" id="form">
