</div>

<script>
const TIERS = [
  ['T5凡人级', '普通人、士兵、未觉醒的法师'],
  ['T4精英级', '军官、初阶法师、黑帮头目、改造者'],
  ['T3英雄级', '顶尖刺客、高阶法师，可左右小型战役'],
  ['T2半神级', '飞升者、暗裔，能量足以改变地形'],
  ['T1星神级', '星灵宿主级，世界级威胁（慎选）']
];
const REGIONS = ['皮尔特沃夫', '祖安', '德玛西亚', '诺克萨斯', '艾欧尼亚', '弗雷尔卓德', '恕瑞玛', '比尔吉沃特', '巨神峰', '暗影岛', '以绪塔尔', '班德尔城'];
const CHARACTERS = ['金克丝', '莫甘娜', '拉克丝', '卡特琳娜', '迦娜', '阿狸', '阿卡丽', '萨勒芬妮', '蔚', '凯特琳', '泽丽', '烈娜塔', '梅尔', '卡密尔',
  '安蓓萨', '希尔科', '杰斯', '黑默丁格', '辛吉德', '维克托', '艾克', '沃里克', '布里茨', '扎克', '蒙多', '伊泽瑞尔', '图奇', '瑞兹', '佐伊',
  '奥莉安娜', '艾瑞莉亚', '卡尔玛', '辛德拉', '莉莉娅', '霞', '洛', '芸阿娜', '李青', '亚索', '永恩', '艾翁', '易', '悟空', '慧', '烬', '慎',
  '凯南', '劫', '凯隐', '锐雯', '瑟提', '韦鲁斯', '莎弥拉', '乐芙兰', '贝蕾亚', '卡西奥佩娅', '芮尔', '伊莉丝', '凯尔', '娑娜', '菲奥娜',
  '薇恩', '伊芙琳', '希瓦娜', '波比', '奎因', '斯维因', '泰隆', '赛恩', '厄加特', '德莱厄斯', '弗拉基米尔', '克烈', '德莱文', '莫德凯撒',
  '盖伦', '嘉文四世', '加里奥', '塞拉斯', '赵信', '卢锡安', '费德提克', '萨科', '塔姆'];
const STAGE_VALUE = { 戒备: -50, 陌生: 100, 熟悉: 450, 恋慕: 750, 不渝: 920 };
const EVENT_PRESETS = [
  ['酒馆偶遇', '在一间嘈杂的酒馆里，一场意外的冲突把我卷了进去。'],
  ['被追捕中', '我正被当地的执法者或军队追捕，必须尽快找到藏身之处。'],
  ['接下委托', '我刚刚接下一份报酬丰厚却来历不明的委托，雇主约我在今晚碰面。'],
  ['异象降临', '天空裂开了一道发光的缝隙，周围的魔法开始失控。'],
  ['旧识重逢', '一位多年未见的故人突然出现在我面前，带来了一个坏消息。'],
  ['初来乍到', '我刚刚抵达这里，身上只剩一点盘缠，对这座城市一无所知。']
];

let tier = 'T5凡人级';
let dreamOn = false;

function $id(id) { return document.getElementById(id); }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

function renderTiers() {
  $id('tiers').innerHTML = TIERS.map(([t, d]) =>
    '<div class="tier' + (t === tier ? ' on' : '') + '" data-tier="' + t + '"><b>' + t + '</b><small>' + d + '</small></div>').join('');
  $id('tier-hint').textContent = tier === 'T1星神级' ? 'T1 意味着你足以与星灵抗衡，大部分冲突将失去悬念。' : '';
}
function addRel(name, stage, desc) {
  const row = document.createElement('div');
  row.className = 'rel';
  row.innerHTML =
    '<label>角色<select class="rel-name">' + CHARACTERS.map(c => '<option' + (c === name ? ' selected' : '') + '>' + c + '</option>').join('') + '</select></label>' +
    '<label>关系阶段<select class="rel-stage">' + Object.keys(STAGE_VALUE).map(s => '<option' + (s === (stage || '熟悉') ? ' selected' : '') + '>' + s + '</option>').join('') + '</select></label>' +
    '<label class="rel-desc">关系描述<input class="rel-text" placeholder="例如 一同在下城长大的青梅竹马" value="' + esc(desc || '') + '"></label>' +
    '<button class="btn btn-x" title="移除">✕</button>';
  $id('rels').appendChild(row);
}

function init() {
  $id('f-region').innerHTML = REGIONS.map(r => '<option>' + r + '</option>').join('');
  $id('event-chips').innerHTML = EVENT_PRESETS.map(([k], i) => '<span class="chip" data-i="' + i + '">' + k + '</span>').join('');
  renderTiers();
}

document.addEventListener('click', ev => {
  const t = ev.target.closest('.tier');
  if (t) { tier = t.dataset.tier; renderTiers(); return; }
  if (ev.target.id === 'add-rel') { addRel(); return; }
  const x = ev.target.closest('.btn-x');
  if (x) { x.closest('.rel').remove(); return; }
  const chip = ev.target.closest('.chip');
  if (chip) { $id('f-event').value = EVENT_PRESETS[Number(chip.dataset.i)][1]; return; }
  if (ev.target.closest('#dream-switch')) {
    dreamOn = !dreamOn;
    $id('dream-switch').classList.toggle('on', dreamOn);
    $id('dream-extra').classList.toggle('on', dreamOn);
    return;
  }
  if (ev.target.id === 'go') submit();
});

function collect() {
  const rels = Array.from(document.querySelectorAll('.rel')).map(r => ({
    name: r.querySelector('.rel-name').value,
    stage: r.querySelector('.rel-stage').value,
    desc: r.querySelector('.rel-text').value.trim()
  }));
  return {
    name: $id('f-name').value.trim(),
    gender: $id('f-gender').value,
    age: Number($id('f-age').value) || 0,
    look: $id('f-look').value.trim(),
    bg: $id('f-bg').value.trim(),
    tier,
    region: $id('f-region').value,
    place: $id('f-place').value.trim(),
    rels,
    event: $id('f-event').value.trim(),
    dream: dreamOn,
    dreamWho: $id('f-dream-who').value.trim()
  };
}

function stageOf(v) { return v < 0 ? '戒备' : v < 350 ? '陌生' : v < 700 ? '熟悉' : v < 900 ? '恋慕' : '不渝'; }

function applyToStat(stat, f) {
  _.set(stat, '主角.档案', { 姓名: f.name, 性别: f.gender, 年龄: f.age, 外貌: f.look, 背景: f.bg });
  _.set(stat, '主角.基础能级', f.tier);
  _.set(stat, '世界状态.大地点', f.region);
  _.set(stat, '世界状态.具体地点', f.place || '待定');
  _.set(stat, '世界状态.梦境', { 是否处于梦境叙事中: f.dream ? '是' : '否', 核心参与者: f.dream ? f.dreamWho : '' });
  f.rels.forEach(r => {
    const v = STAGE_VALUE[r.stage];
    const old = _.get(stat, ['近期NPC', r.name], {});
    _.set(stat, ['近期NPC', r.name], _.merge({ 基础能级: '待定', 状态: { 伤势等级: '无伤', 魔法能量透支状态: '正常' }, 物品栏: {} }, old,
      { 好感度: v, 与主角关系: r.desc || r.stage, _关系阶段: stageOf(v) }));
  });
  return stat;
}

function buildMessage(f) {
  const lines = ['【开局设定】',
    '姓名：' + f.name + '　性别：' + f.gender + (f.age ? '　年龄：' + f.age : ''),
    '战力能级：' + f.tier,
    '所在地：' + f.region + (f.place ? '·' + f.place : '')];
  if (f.look) lines.push('外貌：' + f.look);
  if (f.bg) lines.push('背景：' + f.bg);
  if (f.rels.length) lines.push('人际关系：' + f.rels.map(r => r.name + '（' + r.stage + (r.desc ? '，' + r.desc : '') + '）').join('；'));
  lines.push('开场事件：' + (f.event || '由叙述者根据所在地区安排'));
  if (f.dream) lines.push('梦境模式：开启' + (f.dreamWho ? '，核心参与者：' + f.dreamWho : ''));
  lines.push('', '请根据以上设定，以<user>为主角写出故事的开场。');
  return lines.join('\n');
}

async function writeVariables(f) {
  if (typeof getCurrentMessageId !== 'function') return;
  const opt = { type: 'message', message_id: getCurrentMessageId() };
  let mvu = null;
  try {
    if (typeof waitGlobalInitialized === 'function') {
      mvu = await Promise.race([waitGlobalInitialized('Mvu'), new Promise(r => setTimeout(() => r(null), 4000))]);
    }
  } catch (e) { mvu = null; }
  const M = (typeof Mvu !== 'undefined' && Mvu) ? Mvu : mvu;
  if (M && M.getMvuData && M.replaceMvuData) {
    const data = M.getMvuData(opt) || {};
    data.stat_data = applyToStat(data.stat_data || {}, f);
    await M.replaceMvuData(data, opt);
  } else if (typeof updateVariablesWith === 'function') {
    updateVariablesWith(vars => { vars.stat_data = applyToStat(vars.stat_data || {}, f); return vars; }, opt);
  }
}

async function submit() {
  const f = collect();
  const msg = $id('msg');
  if (!f.name) { msg.className = 'msg'; msg.textContent = '请填写姓名'; $id('f-name').focus(); return; }
  $id('go').disabled = true;
  msg.className = 'msg ok';
  msg.textContent = '正在写入设定……';
  try {
    await writeVariables(f);
    const text = buildMessage(f);
    if (typeof createChatMessages === 'function' && typeof triggerSlash === 'function') {
      await createChatMessages([{ role: 'user', message: text }]);
      msg.textContent = '设定完成，故事即将开始……';
      await triggerSlash('/trigger');
    } else {
      console.log(text);
      msg.textContent = '（预览模式）设定已生成，请查看控制台';
      $id('go').disabled = false;
    }
  } catch (e) {
    msg.className = 'msg';
    msg.textContent = '出错了：' + (e && e.message ? e.message : e);
    $id('go').disabled = false;
  }
}

init();
</script>
</body>
