    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>符文之地 场景卡</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }

        .acg-scene-card-root {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            background: transparent; padding: 10px; width: 100%;
        }

        /* 主题色系统定义 */
        :root {
            --bg-color: #ffffff;
            --acg-dark: #1e293b;
            --acg-danger: #ef4444;
            --shadow-soft: 0 10px 30px rgba(15, 23, 42, 0.08);
            --paper-bg: #fdfbf7;

            /* 默认色 */
            --theme-default: #3b82f6;

            --theme-jinx: #e05fa8;

            --theme-seraphine: #f29ac0;

            --theme-lux: #e8b84a;

            --theme-ahri: #e36a6a;

            --theme-akali: #2fb59a;

            --theme-morgana: #7d5bbf;

            --theme-janna: #5fb8d0;


            --theme-katarina: #c8323c;

            --theme-vi: #e0507a;

            --theme-caitlyn: #4f7fd6;

            --theme-zeri: #7cc23f;
            --theme-syndra: #8e4fd0;

            --acg-accent: var(--theme-default);
        }

        .wrapper.theme-jinx { --acg-accent: var(--theme-jinx); }
        .wrapper.theme-seraphine { --acg-accent: var(--theme-seraphine); }
        .wrapper.theme-lux { --acg-accent: var(--theme-lux); }
        .wrapper.theme-ahri { --acg-accent: var(--theme-ahri); }
        .wrapper.theme-akali { --acg-accent: var(--theme-akali); }
        .wrapper.theme-morgana { --acg-accent: var(--theme-morgana); }
        .wrapper.theme-janna { --acg-accent: var(--theme-janna); }
        .wrapper.theme-katarina { --acg-accent: var(--theme-katarina); }
        .wrapper.theme-vi { --acg-accent: var(--theme-vi); }
        .wrapper.theme-caitlyn { --acg-accent: var(--theme-caitlyn); }
        .wrapper.theme-zeri { --acg-accent: var(--theme-zeri); }
        .wrapper.theme-syndra { --acg-accent: var(--theme-syndra); }

        .acg-scene-card-root .wrapper {
            position: relative; max-width: 820px; margin: 0 auto;
            border-radius: 16px; overflow: hidden; background: var(--bg-color);
            box-shadow: var(--shadow-soft), 0 1px 3px rgba(15, 23, 42, 0.03);
            min-height: 480px; transition: min-height 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), height 0.5s ease;
            border: 1px solid rgba(226, 232, 240, 0.6);
            transform: translateZ(0); -webkit-transform: translateZ(0);
        }

        .acg-scene-card-root .wrapper.is-minimized {
            min-height: 56px; height: 56px; background: #f8fafc;
        }

        .acg-scene-card-root .main-content {
            opacity: 0; transform: translateY(16px);
            transition: opacity 0.7s ease 0.2s, transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) 0.2s;
            display: flex; flex-direction: column; position: relative; z-index: 10;
            min-height: 480px; background: var(--bg-color);
            will-change: opacity, transform;
        }
        .acg-scene-card-root .main-content.visible { opacity: 1; transform: translateY(0); }
        .acg-scene-card-root .main-content.instant { transition: none !important; opacity: 1; transform: translateY(0); }
        .acg-scene-card-root .wrapper.is-minimized .main-content { opacity: 0; pointer-events: none; visibility: hidden; position: absolute; }

        /* 主视觉区 */
        .acg-scene-card-root .hero-section {
            width: 100%; aspect-ratio: 21 / 9; background: #e2e8f0;
            position: relative; overflow: hidden;
            border-bottom: 2px dashed rgba(203, 213, 225, 0.5);
            transform: translateZ(0);
        }
        .acg-scene-card-root .hero-section::after {
            content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 50%;
            background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0.7) 30%, transparent 100%);
            pointer-events: none; z-index: 2;
        }
        .acg-scene-card-root .hero-placeholder { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #94a3b8; font-size: 11px; letter-spacing: 3px; text-transform: uppercase; }
        .acg-scene-card-root .static-img { width: 100%; height: 100%; object-fit: cover; object-position: center 20%; display: block; cursor: zoom-in; transition: transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1); will-change: transform; }
        @media (hover: hover) { .acg-scene-card-root .hero-section:hover .static-img { transform: scale(1.03); } }

        /* 角色铭牌 */
