            transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), border-color 0.4s;
            will-change: transform;
        }
        @media (hover: hover) { .acg-scene-card-root .role-badge:hover { transform: translateY(-4px); } }
        .acg-scene-card-root .role-names { display: flex; flex-direction: column; }
        .acg-scene-card-root .role-names .role-sub { font-size: 9px; color: #94a3b8; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 2px; font-family: monospace; }
        .acg-scene-card-root .role-names .role-main { font-size: 16px; font-weight: 900; color: var(--acg-dark); letter-spacing: 2px; font-family: serif;}

        /* 内容区 */
        .acg-scene-card-root .content-section {
            padding: 40px 36px 24px 36px; display: flex; flex-direction: column; flex-grow: 1; position: relative;
            background-image: radial-gradient(rgba(203, 213, 225, 0.4) 1px, transparent 1px);
            background-size: 16px 16px;
        }

        .acg-scene-card-root .info-grid { display: grid; grid-template-columns: 1.2fr 0.8fr 1fr; gap: 16px; margin-bottom: 30px; position: relative; z-index: 11; }
        .acg-scene-card-root .grid-item {
            display: flex; flex-direction: column; background: rgba(255, 255, 255, 0.85);
