        }
        @media (hover: hover) { .acg-scene-card-root .grid-item:hover { background: #ffffff; border-color: var(--acg-accent); box-shadow: 0 6px 16px rgba(15, 23, 42, 0.05); transform: translateY(-2px); } }
        .acg-scene-card-root .grid-item::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; background: var(--acg-accent); opacity: 0.5; transition: opacity 0.3s ease; }
        @media (hover: hover) { .acg-scene-card-root .grid-item:hover::before { opacity: 1; } }
        .acg-scene-card-root .grid-label { font-size: 10px; color: #94a3b8; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 4px; font-family: monospace; }
        .acg-scene-card-root .grid-value { font-size: 13px; font-weight: 800; color: #334155; letter-spacing: 0.5px; word-break: break-word; }

        /* 独白卡片 */
        .acg-scene-card-root .monologue-card {
            background-color: var(--paper-bg);
            background-image: repeating-linear-gradient(transparent, transparent 27px, rgba(203, 213, 225, 0.4) 27px, rgba(203, 213, 225, 0.4) 28px);
            line-height: 28px;
            border: 1px solid rgba(226, 232, 240, 0.8); border-radius: 8px;
            padding: 24px 120px 24px 36px; margin-bottom: 20px; position: relative; z-index: 11;
            box-shadow: 2px 4px 15px rgba(0,0,0,0.03); color: #475569; font-size: 14px;
            min-height: 100px; transition: border-color 0.3s;
        }
        @media (hover: hover) { .acg-scene-card-root .monologue-card:hover { border-color: rgba(203, 213, 225, 1); } }
        .acg-scene-card-root .monologue-card::before { content: "“"; position: absolute; top: 12px; left: -8px; font-size: 60px; color: var(--acg-accent); opacity: 0.15; font-family: Georgia, serif; line-height: 1; font-weight: bold; transition: opacity 0.3s;}
        .acg-scene-card-root .monologue-card::after { content: "”"; position: absolute; bottom: -20px; right: 10px; font-size: 60px; color: var(--acg-accent); opacity: 0.15; font-family: Georgia, serif; line-height: 1; font-weight: bold; transition: opacity 0.3s;}
        @media (hover: hover) { .acg-scene-card-root .monologue-card:hover::before, .acg-scene-card-root .monologue-card:hover::after { opacity: 0.25; } }

        /* Q版拖拽小人 */
        .acg-scene-card-root .chibi-drag-wrap {
            position: absolute; right: 5px; top: -15px;
            width: 110px; height: 110px; z-index: 25;
            cursor: grab; user-select: none; touch-action: none;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(255,255,255,0.7) 20%, rgba(255,255,255,0) 65%);
            will-change: left, top, transform;
            transform: translateZ(0);
        }
        .acg-scene-card-root .chibi-drag-wrap:active { cursor: grabbing; }
        .acg-scene-card-root .chibi-avatar {
            width: 100%; height: 100%; object-fit: contain;
            pointer-events: none; border-radius: 50%;
            -webkit-mask-image: radial-gradient(circle, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 95%);
            mask-image: radial-gradient(circle, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 95%);
            animation: floatChibi 4s ease-in-out infinite alternate;
            transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
            transform: translateZ(0);
        }
        @keyframes floatChibi { 0% { transform: translateY(0) rotate(-3deg); } 100% { transform: translateY(-10px) rotate(3deg); } }

        @media (hover: hover) { .acg-scene-card-root .chibi-drag-wrap:hover:not(.is-dragging) .chibi-avatar { transform: scale(1.1) translateY(-5px); } }
        .acg-scene-card-root .chibi-drag-wrap.is-dragging .chibi-avatar {
            animation: dragStruggle 0.3s ease-in-out infinite alternate !important;
            filter: drop-shadow(0 8px 15px rgba(0,0,0,0.25));
        }
        @keyframes dragStruggle { 0% { transform: scale(1.1) translateY(-8px) rotate(-6deg); } 100% { transform: scale(1.1) translateY(-8px) rotate(6deg); } }

        /* 底部控制栏 */
        .acg-scene-card-root .decor-footer { margin-top: auto; display: flex; align-items: center; justify-content: space-between; padding-top: 20px; border-top: 1px dashed rgba(203, 213, 225, 0.6); position: relative; z-index: 12; flex-wrap: wrap; gap: 10px;}
        .acg-scene-card-root .stream-line { flex-grow: 1; height: 1px; background: #e2e8f0; margin: 0 20px; position: relative; overflow: hidden; min-width: 50px; }
        .acg-scene-card-root .stream-head { position: absolute; top: -1px; left: 0; height: 3px; width: 40px; background: var(--acg-accent); opacity: 0.6; animation: flowRight 3s ease-in-out infinite; }
        @keyframes flowRight { 0% { left: -40px; opacity: 1; } 80% { left: 100%; opacity: 1; } 100% { left: 100%; opacity: 0; } }

        .acg-scene-card-root .elegant-spectrum { display: flex; gap: 3px; align-items: flex-end; height: 12px; }
        .acg-scene-card-root .esp-bar { width: 3px; background: #cbd5e1; border-radius: 1.5px; }
        .acg-scene-card-root .esp-bar:nth-child(1) { animation: bounce 1.2s ease infinite alternate; }
        .acg-scene-card-root .esp-bar:nth-child(2) { animation: bounce 0.8s ease infinite alternate 0.2s; }
        .acg-scene-card-root .esp-bar:nth-child(3) { animation: bounce 1.5s ease infinite alternate 0.4s; }
        @keyframes bounce { 0% { height: 3px; } 100% { height: 12px; background: var(--acg-accent); } }

        .acg-scene-card-root .sys-group { display: flex; align-items: center; gap: 8px;}
        .acg-scene-card-root .system-text { font-size: 9px; color: #94a3b8; letter-spacing: 1.5px; font-family: monospace; display: none;}
        @media (min-width: 600px) { .acg-scene-card-root .system-text { display: block; } }

        .acg-scene-card-root .db-btn, .acg-scene-card-root .min-btn, .acg-scene-card-root .expand-btn, .acg-scene-card-root .cal-btn, .acg-scene-card-root .dark-btn {
            font-family: monospace; font-size: 10px; font-weight: bold; padding: 6px 12px;
            border-radius: 6px; cursor: pointer; transition: 0.3s; letter-spacing: 1px; display: flex; align-items: center; gap: 4px;
        }
        .acg-scene-card-root .db-btn, .acg-scene-card-root .cal-btn, .acg-scene-card-root .dark-btn { border: 1px solid #cbd5e1; color: #64748b; background: rgba(255,255,255,0.8); box-shadow: 0 2px 6px rgba(0,0,0,0.03); }
        @media (hover: hover) { .acg-scene-card-root .db-btn:hover, .acg-scene-card-root .cal-btn:hover, .acg-scene-card-root .dark-btn:hover { background: var(--acg-accent); color: #fff; border-color: var(--acg-accent); box-shadow: 0 6px 16px rgba(0,0,0,0.15); transform: translateY(-1px); } }
        .acg-scene-card-root .min-btn { border: 1px solid transparent; color: #94a3b8; background: transparent; }
        @media (hover: hover) { .acg-scene-card-root .min-btn:hover { color: var(--acg-accent); } }
        .acg-scene-card-root svg { width: 12px; height: 12px; fill: currentColor; }

        .acg-scene-card-root .reset-btn { position: absolute; top: 12px; right: 12px; z-index: 30; background: rgba(255, 255, 255, 0.6); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid rgba(255,255,255,0.8); color: #64748b; font-size: 9px; padding: 6px 12px; border-radius: 16px; cursor: pointer; display: flex; align-items: center; gap: 4px; box-shadow: 0 2px 6px rgba(0,0,0,0.04); transition: all 0.3s ease; }
        @media (hover: hover) { .acg-scene-card-root .reset-btn:hover { background: #ffffff; color: var(--acg-accent); transform: translateY(-1px); } }
        .acg-scene-card-root .wrapper.is-minimized .reset-btn { opacity: 0; pointer-events: none; visibility: hidden;}

        /* 伸缩音乐播放器 */
        .acg-scene-card-root .music-player-widget {
