        .acg-scene-card-root .m-track-info { font-size: 10px; font-family: monospace; color: #64748b; font-weight: bold; letter-spacing: 1px; margin-left: 10px; background: #f1f5f9; padding: 4px 8px; border-radius: 12px;}
        .acg-scene-card-root .wrapper.is-minimized .music-player-widget { opacity: 0; pointer-events: none; visibility: hidden; }

        /* 迷你条封皮 */
        .acg-scene-card-root .mini-bar {
            position: absolute; top: 0; left: 0; width: 100%; height: 56px;
            background: linear-gradient(90deg, #1e293b 0%, #334155 100%);
            display: flex; align-items: center; justify-content: space-between; padding: 0 20px;
            opacity: 0; pointer-events: none; transition: opacity 0.4s ease; z-index: 100;
