        .acg-scene-card-root .mini-name { color: #ffffff; font-weight: 900; font-size: 13px; }
        .acg-scene-card-root .expand-btn { background: #e2e8f0; color: #1e293b; border-color: transparent; clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%); }
