        .gallery-item { position: relative; aspect-ratio: 21/9; background: #e2e8f0; border-radius: 4px; overflow: hidden; cursor: zoom-in; border: 1px solid rgba(148,163,184,0.3); box-shadow: 0 4px 15px rgba(0,0,0,0.05); transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); transform: translateZ(0);}
