        .gallery-pagination { display: flex; justify-content: center; align-items: center; gap: 30px; padding: 24px; background: linear-gradient(to top, rgba(241,245,249,1) 50%, rgba(241,245,249,0) 100%); border-top: 1px solid rgba(203,213,225,0.4); font-family: monospace; z-index: 10; margin-top: auto;}
        .acg-page-btn { background: #ffffff; border: 1px solid #cbd5e1; color: #475569; padding: 10px 30px; border-radius: 4px; font-weight: bold; font-size: 11px; letter-spacing: 3px; cursor: pointer; transition: all 0.3s; clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%); display: flex; align-items: center; gap: 8px; }
