        .nsfw-container { display: none; flex-direction: column; padding: 30px 50px; }
        .gallery-modal.mode-nsfw .normal-container { display: none; }
        .gallery-modal.mode-nsfw .nsfw-container { display: flex; }
        .nsfw-section { margin-bottom: 40px; }
        .nsfw-section-title { font-size: 16px; font-weight: 900; color: #ef4444; font-family: monospace; letter-spacing: 4px; padding-bottom: 10px; margin-bottom: 20px; border-bottom: 1px solid rgba(239, 68, 68, 0.3); display: flex; align-items: center; gap: 10px; }
