        .nsfw-item { position: relative; aspect-ratio: 832/1216; background: #0f172a; border-radius: 6px; overflow: hidden; cursor: zoom-in; border: 1px solid rgba(239, 68, 68, 0.2); box-shadow: 0 4px 15px rgba(0,0,0,0.2); transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); transform: translateZ(0);}
