        .nsfw-item::before { content: attr(data-label); position: absolute; top: 0; left: 0; background: #ef4444; color: #fff; font-size: 9px; font-weight: 800; padding: 4px 10px 4px 6px; z-index: 2; font-family: monospace; letter-spacing: 1px; clip-path: polygon(0 0, 100% 0, 80% 100%, 0 100%); }
