    <script>
        (function() {
            /* ================= 全局智能图片路由 ================= */
            if (!window.acgGetBaseUrl) {
                window.acgGetBaseUrl = function(roleKey, isNsfw) {
                    return (window.RT_IMG_BASE || 'https://testingcf.jsdelivr.net/gh/TakaoTay/art@main/') + (isNsfw ? 'nsfw/' : '');
                };
            }

            /* ================= 核心引擎1：伸缩音乐播放器 ================= */
            if (!window.ACG_MUSIC_ENGINE_INIT) {
                window.ACG_MUSIC_ENGINE_INIT = true;
                window.acgMusicState = {
                    currentTrack: 1,
                    totalTracks: 10,
                    isPlaying: false,
                    audioObj: new Audio((window.RT_BGM_BASE || '') ? (window.RT_BGM_BASE || '') + '1.mp3' : undefined),
                    volume: 0.5,
                    avatarUrl: ''
                };
                window.acgMusicState.audioObj.volume = window.acgMusicState.volume;
                window.acgMusicState.audioObj.loop = false;

                window.acgMusicState.audioObj.addEventListener('ended', function() {
                    window.acgMusicChangeTrack(null, 1);
                });

                var rRoles = ['lux', 'seraphine', 'ahri', 'jinx', 'akali', 'morgana', 'janna', 'katarina', 'vi', 'caitlyn', 'zeri'];
                var rEmos = ['kx', 'sq', 'wq', 'pd', 'rc', 'ty'];
                var randRole = rRoles[Math.floor(Math.random() * rRoles.length)];
                var randEmo = rEmos[Math.floor(Math.random() * rEmos.length)];

                window.acgMusicState.avatarUrl = window.acgGetBaseUrl(randRole, false) + randRole + '_' + randEmo + '_q.png';

                window.acgMusicTogglePlay = function(e) {
                    if(e) { e.preventDefault(); e.stopPropagation(); }
                    var st = window.acgMusicState;
                    if (st.isPlaying) {
                        st.audioObj.pause();
                        st.isPlaying = false;
                    } else {
                        st.audioObj.play().catch(function(err){ console.log("Audio play error", err); });
                        st.isPlaying = true;
                    }
                    window.acgMusicUpdateUI();
                };

                window.acgMusicChangeTrack = function(e, delta) {
                    if(e) { e.preventDefault(); e.stopPropagation(); }
                    var st = window.acgMusicState;
                    st.currentTrack += delta;
                    if(st.currentTrack > st.totalTracks) st.currentTrack = 1;
                    if(st.currentTrack < 1) st.currentTrack = st.totalTracks;

                    st.audioObj.src = (window.RT_BGM_BASE || '') + st.currentTrack + '.mp3';
                    if (st.isPlaying) {
                        st.audioObj.play().catch(function(err){});
                    }
                    window.acgMusicUpdateUI();
                };

                window.acgMusicChangeVol = function(e, val) {
                    if(e) e.stopPropagation();
                    window.acgMusicState.volume = val / 100;
                    window.acgMusicState.audioObj.volume = window.acgMusicState.volume;
                };

                window.acgMusicToggleExpand = function(e) {
                    if(e) { e.preventDefault(); e.stopPropagation(); }
                    var widgets = document.querySelectorAll('.music-player-widget');
                    widgets.forEach(function(widget) {
                        widget.classList.toggle('collapsed');
                    });
                };

                window.acgMusicUpdateUI = function() {
                    var widgets = document.querySelectorAll('.music-player-widget');
                    widgets.forEach(function(w) {
                        var playIcon = w.querySelector('.play-icon');
                        var pauseIcon = w.querySelector('.pause-icon');
                        var trackInfo = w.querySelector('.m-track-info');
                        if (window.acgMusicState.isPlaying) {
                            if(playIcon) playIcon.style.display = 'none';
                            if(pauseIcon) pauseIcon.style.display = 'block';
                        } else {
                            if(playIcon) playIcon.style.display = 'block';
                            if(pauseIcon) pauseIcon.style.display = 'none';
                        }
                        if(trackInfo) {
                            trackInfo.innerText = 'TRACK ' + (window.acgMusicState.currentTrack < 10 ? '0' : '') + window.acgMusicState.currentTrack;
                        }
                    });
                };
            }

            /* ================= 核心引擎2：图鉴 ================= */
            if (!window.ACG_GALLERY_ENGINE_INIT) {
                window.ACG_GALLERY_ENGINE_INIT = true;
                window.ACG_ROLE_PROFILES = {
                    'jinx': { aliases: ['金克丝', '爆爆', 'Jinx'], name: '金克丝', count: 25 },
                    'seraphine': { aliases: ['萨勒芬妮', '小芬', 'Seraphine'], name: '萨勒芬妮', count: 25 },
                    'lux': { aliases: ['拉克丝', '拉克丝安娜', '冕卫', 'Lux'], name: '拉克丝', count: 25 },
                    'ahri': { aliases: ['阿狸', '九尾狐', 'Ahri'], name: '阿狸', count: 25 },
                    'akali': { aliases: ['阿卡丽', 'Akali'], name: '阿卡丽', count: 25 },
                    'morgana': { aliases: ['莫甘娜', '面纱女士', 'Morgana'], name: '莫甘娜', count: 25 },
                    'janna': { aliases: ['迦娜', '风之化身', 'Janna'], name: '迦娜', count: 25 },
                    'katarina': { aliases: ['卡特琳娜', '卡特', 'Katarina'], name: '卡特琳娜', count: 25 },
                    'vi': { aliases: ['蔚', '皮城执法官蔚', 'Vi'], name: '蔚', count: 25 },
                    'caitlyn': { aliases: ['凯特琳', '凯特琳·基拉曼', 'Caitlyn'], name: '凯特琳', count: 25 },
                    'zeri': { aliases: ['泽丽', 'Zeri'], name: '泽丽', count: 25 },
                    'syndra': { aliases: ['辛德拉', '黑暗元首', 'Syndra'], name: '辛德拉', count: 25 }
                };

