                    { key: 'kj', name: '口交 (ORAL)' }, { key: 'zj', name: '足交 (FOOT)' }, { key: 'rj', name: '乳交 (TIT)' },
                    { key: 'nsw', name: '女上位 (COWGIRL)' }, { key: 'zcw', name: '正常位 (MISSIONARY)' }, { key: 'hrw', name: '后入位 (DOGGY)' }
                ];

                window.ACG_ALL_PICS = [];
                for (var role in window.ACG_ROLE_PROFILES) {
                    for (var i = 1; i <= window.ACG_ROLE_PROFILES[role].count; i++) {
                        window.ACG_ALL_PICS.push({ role: role, file: role + '_' + i });
                    }
                }

                window.acgHandleImgError = function(imgElement, backupUrl) {
                    if (!imgElement.getAttribute('data-retried')) {
                        imgElement.setAttribute('data-retried', 'true'); imgElement.src = backupUrl;
                    } else {
                        imgElement.style.opacity = '0';
                        var parent = imgElement.parentElement;
                        if (parent && (parent.classList.contains('acg-hero-clip') || parent.classList.contains('hero-section'))) { parent.innerHTML += '<div class="hero-placeholder">IMG LOST</div>'; }
                    }
                };

                /* 手机端防底层滚动穿透 */
                function preventScroll(e) { e.preventDefault(); }

                window.acgTriggerLightbox = function(event, src) {
                    if(event) { event.preventDefault(); event.stopPropagation(); }
                    var oldBox = document.getElementById('lightbox-modal'); if (oldBox) oldBox.remove();
                    var box = document.createElement('div'); box.id = 'lightbox-modal'; box.className = 'lightbox-modal';
                    if (localStorage.getItem('acg-scene-dark') === 'true') { box.classList.add('dark-mode'); }
                    box.onclick = function() {
                        box.classList.remove('show');
                        document.body.removeEventListener('touchmove', preventScroll);
                        setTimeout(function(){ box.remove(); }, 400);
                    };
                    box.innerHTML = '<div class="lightbox-content" onclick="event.stopPropagation();"><img src="' + src + '"></div>';
                    document.body.appendChild(box);
                    /* 打开Lightbox时彻底禁用页面滚动 */
                    document.body.addEventListener('touchmove', preventScroll, { passive: false });
                    setTimeout(function(){ box.classList.add('show'); }, 50);
                };

                window.acgGalleryState = { mode: 'NORMAL', filter: 'ALL', currentPage: 1, itemsPerPage: 10 };
                window.acgSwitchMode = function(newMode) {
                    if(window.acgGalleryState.mode === newMode) return;
                    window.acgGalleryState.mode = newMode;
                    var modal = document.getElementById('gallery-modal'); if(!modal) return;
                    if(newMode === 'NSFW') { modal.classList.add('mode-nsfw'); window.acgGalleryState.filter = Object.keys(window.ACG_ROLE_PROFILES)[0]; }
                    else { modal.classList.remove('mode-nsfw'); window.acgGalleryState.filter = 'ALL'; }
                    var tabsHtml = '';
                    if (newMode === 'NORMAL') { tabsHtml += '<div class="acg-tab-btn" data-target="ALL" onclick="window.acgRenderGalleryGrid(\'ALL\')">ALL</div>'; }
                    for (var r in window.ACG_ROLE_PROFILES) { tabsHtml += '<div class="acg-tab-btn" data-target="' + r + '" onclick="window.acgRenderGalleryGrid(\'' + r + '\')">' + window.ACG_ROLE_PROFILES[r].name.toUpperCase() + '</div>'; }
                    document.getElementById('gallery-tabs').innerHTML = tabsHtml;
                    var switchBtn = document.getElementById('mode-switch-btn');
                    if(newMode === 'NORMAL') { switchBtn.innerHTML = 'SWITCH TO CLASSIFIED'; switchBtn.setAttribute('onclick', 'window.acgSwitchMode(\'NSFW\')'); }
                    else { switchBtn.innerHTML = 'SWITCH TO NORMAL'; switchBtn.setAttribute('onclick', 'window.acgSwitchMode(\'NORMAL\')'); }
