                        if (idx === -1) return;
                        var key = line.slice(0, idx).trim();
                        var val = line.slice(idx + 1).trim();
                        if (key.includes('日期')) result.date = formatDetailedDate(val);
                        else if (key.includes('时间')) result.time = val;
                        else if (key.includes('地点')) result.location = val;
