                            dragWrap.classList.add('is-dragging');
                            if (chibiImg && urlDrag) chibiImg.src = urlDrag;

                            startX = e.clientX;
                            startY = e.clientY;
                            initialX = dragWrap.offsetLeft;
                            initialY = dragWrap.offsetTop;

                            dragWrap.style.left = initialX + 'px';
                            dragWrap.style.right = 'auto';

                            e.preventDefault();

                            currentX = startX;
                            currentY = startY;
                            rAF = requestAnimationFrame(moveAvatar);
                        };

                        var onMouseMove = function(e) {
                            if (!isDragging) return;
