                                    var rect = dragWrap.getBoundingClientRect();
                                    var clientX = e.clientX || (e.changedTouches && e.changedTouches[0] ? e.changedTouches[0].clientX : 0);
                                    var clientY = e.clientY || (e.changedTouches && e.changedTouches[0] ? e.changedTouches[0].clientY : 0);
                                    var isHover = (clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom);
                                    chibiImg.src = isHover && urlHover ? urlHover : urlDefault;
