                            startY = touch.clientY;
                            initialX = dragWrap.offsetLeft;
                            initialY = dragWrap.offsetTop;
                            dragWrap.style.left = initialX + 'px';
                            dragWrap.style.right = 'auto';

                            currentX = startX;
                            currentY = startY;
                            rAF = requestAnimationFrame(moveAvatar);
