                            if (!isDragging) return;
                            e.preventDefault(); /* 绝对防止屏幕跟着一起上下乱滑！ */
                            currentX = e.touches[0].clientX;
                            currentY = e.touches[0].clientY;
                        }, {passive: false});

                        document.addEventListener('touchend', onMouseUp);
                    }
                }, 100);
            }

            try { runEngine(); } catch(error) { rootNode.innerHTML = '<div class="wrapper"><div class="loading">渲染出错：' + error.message + '</div></div>'; }
        })();
    </script>
