  function scan(root) {
    if (!root || !root.querySelectorAll) return;
    if (root.tagName === 'IMG' || root.hasAttribute && root.hasAttribute('data-default')) fix(root);
    root.querySelectorAll('img,[data-default],[data-backup]').forEach(fix);
  }
  new MutationObserver(function (muts) {
    muts.forEach(function (m) {
      if (m.type === 'attributes') fix(m.target); else m.addedNodes.forEach(scan);
    });
  }).observe(document.documentElement, { subtree: true, childList: true, attributes: true, attributeFilter: ['src', 'data-backup', 'data-default', 'data-hover', 'data-drag'] });
  document.addEventListener('DOMContentLoaded', function () { scan(document.body); });
})();
