            will-change: transform;
        }
        .image-viewer-modal.show img {
            transform: scale(1);
        }

        /* ==================== 独立图库 Modal ==================== */
        .gallery-modal {
            background: rgba(248, 251, 255, 0.98);
            flex-direction: column;
            /* 恢复触摸滚动供图库内容使用 */
            touch-action: auto;
        }

        .gallery-modal-header {
            flex-shrink: 0;
            padding: max(16px, env(safe-area-inset-top)) 20px 16px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 2px dashed rgba(163, 194, 224, 0.3);
            background: #ffffff;
            box-shadow: 0 2px 10px rgba(136, 153, 175, 0.05);
            z-index: 2;
        }

        .gallery-modal-title {
            color: var(--text-main);
            font-size: 14px;
            font-weight: bold;
            letter-spacing: 1px;
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .gallery-modal-title span { color: var(--accent-color); }

        .gallery-modal-close {
            color: var(--text-sub);
            font-size: 12px;
            font-weight: bold;
            cursor: pointer;
            padding: 10px 16px; /* 增大点击热区 */
