            border-radius: 8px;
            border: 1px solid rgba(163, 194, 224, 0.3);
            transition: all 0.2s ease;
            user-select: none;
        }

        .gallery-modal-close:active {
            background: var(--accent-pink);
            color: #fff;
            transform: scale(0.95);
        }

        .gallery-modal-content {
            flex: 1;
            overflow-y: auto;
            padding: 16px;
            padding-bottom: max(16px, env(safe-area-inset-bottom));
            -webkit-overflow-scrolling: touch; /* iOS 流畅滚动 */
            scroll-behavior: smooth;
        }

        .gallery-section {
            margin-bottom: 24px;
            max-width: 1000px;
            margin-left: auto;
            margin-right: auto;
            background: #ffffff;
            padding: 16px;
            border-radius: 12px;
            border: 1px solid rgba(163, 194, 224, 0.25);
            box-shadow: 0 4px 12px rgba(136, 153, 175, 0.05);
        }

        .gallery-section-title {
            font-size: 13px;
            font-weight: bold;
            color: var(--text-main);
            letter-spacing: 1px;
            margin-bottom: 12px;
            padding: 6px 10px;
            background: #f8fbff;
            border-radius: 8px;
            border-left: 4px solid var(--accent-pink);
            display: inline-block;
            border-top: 1px dashed rgba(163, 194, 224, 0.3);
            border-right: 1px dashed rgba(163, 194, 224, 0.3);
            border-bottom: 1px dashed rgba(163, 194, 224, 0.3);
        }

        .gallery-outfit-group {
            margin-bottom: 16px;
        }
        .gallery-outfit-group:last-child {
            margin-bottom: 0;
        }

        .gallery-row {
            display: flex;
            gap: 12px;
            overflow-x: auto;
            padding-bottom: 12px;
            scrollbar-width: none; /* Firefox 隐藏滚动条 */
            -webkit-overflow-scrolling: touch;
            scroll-snap-type: x mandatory;
        }
        .gallery-row::-webkit-scrollbar { display: none; } /* Chrome/Safari 隐藏滚动条 */

        .gallery-thumb {
            flex-shrink: 0;
            width: clamp(90px, 25vw, 110px); /* 响应式缩略图尺寸 */
            aspect-ratio: 2 / 3;
            background: #f8fbff;
            border: 1px solid rgba(163, 194, 224, 0.3);
            border-radius: 8px;
            padding: 4px;
            cursor: zoom-in;
            display: flex;
            flex-direction: column;
            align-items: center;
            scroll-snap-align: start;
        }

        .gallery-thumb:active {
            transform: scale(0.96);
            border-color: var(--accent-color);
        }

        .gallery-thumb img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center top;
            border-radius: 4px;
        }

        .gallery-thumb-label {
            margin-top: 4px;
            color: var(--text-sub);
            font-size: 10px;
            font-weight: bold;
            text-align: center;
            letter-spacing: 1px;
            background: #ffffff;
            padding: 2px 4px;
            border-radius: 4px;
            border: 1px dashed rgba(163, 194, 224, 0.4);
            width: 100%;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        /* ==================== 手机端极限适配 ==================== */
        @media screen and (max-width: 600px) {
            body { padding: 4px; }
            .scene-info-panel { border-radius: 12px; }
            .scene-header { padding: 12px 8px 10px; }
            .meta-row { font-size: 12px; padding: 4px 12px; gap: 4px; }
            .character-container { padding: 12px 8px; }

            .character-grid {
                grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
                gap: 10px;
            }

            .character-card { padding: 4px; border-radius: 10px; }
            .character-name { font-size: 13px; }
            .switch-btn { width: 30px; height: 30px; } /* 保持易触控 */
            .switch-index { font-size: 10px; }

            .gallery-modal-header { padding: max(12px, env(safe-area-inset-top)) 12px 12px; }
            .gallery-modal-content { padding: 12px 8px max(12px, env(safe-area-inset-bottom)); }
            .gallery-section { padding: 10px; margin-bottom: 16px; border-radius: 10px; }
        }

        @media screen and (max-width: 360px) {
            .character-grid {
                grid-template-columns: 1fr;
                gap: 12px;
            }
            .character-card { max-width: 100%; }
            .gallery-thumb { width: 100px; }
        }
    </style>
