    <div class="scene-card-wrapper" id="app-root">
        <div class="scene-info-panel">
            <div class="system-loading">✦ 正在载入符文之地...</div>
        </div>
    </div>

    <script>
        (function() {
            /* ========== 获取消息内容 ========== */
            function getMessageData() {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (!chatMessages || chatMessages.length === 0) return null;
                return chatMessages[0].message;
            }

            /* ========== 全局配置与别名识别 ========== */

            var allCharacters = [
                { name: '金克丝', code: 'jinx', aliases: ['金克丝', '爆爆', 'Jinx'] },
                { name: '萨勒芬妮', code: 'seraphine', aliases: ['萨勒芬妮', '小芬', 'Seraphine'] },
                { name: '拉克丝', code: 'lux', aliases: ['拉克丝', '拉克丝安娜', '冕卫', 'Lux'] },
                { name: '阿狸', code: 'ahri', aliases: ['阿狸', '九尾狐', 'Ahri'] },
                { name: '阿卡丽', code: 'akali', aliases: ['阿卡丽', 'Akali'] },
                { name: '莫甘娜', code: 'morgana', aliases: ['莫甘娜', '面纱女士', 'Morgana'] },
                { name: '迦娜', code: 'janna', aliases: ['迦娜', '风之化身', 'Janna'] },
                { name: '卡特琳娜', code: 'katarina', aliases: ['卡特琳娜', '卡特', 'Katarina'] },
                { name: '蔚', code: 'vi', aliases: ['蔚', '皮城执法官蔚', 'Vi'] },
                { name: '凯特琳', code: 'caitlyn', aliases: ['凯特琳', '凯特琳·基拉曼', 'Caitlyn'] },
                { name: '泽丽', code: 'zeri', aliases: ['泽丽', 'Zeri'] },
                { name: '辛德拉', code: 'syndra', aliases: ['辛德拉', '黑暗元首', 'Syndra'] }
            ];

            var outfitTypes = [
                { label: '日常', code: 'rc' },
                { label: '外出', code: 'wc' },
                { label: '战斗', code: 'zf' }
            ];

            /* 构建支持别名的完整字典 */
            var nameMap = {};
            allCharacters.forEach(function(c) {
                nameMap[c.name] = { code: c.code, displayName: c.name };
                if (c.aliases) {
                    c.aliases.forEach(function(alias) {
                        nameMap[alias] = { code: c.code, displayName: c.name };
                    });
                }
            });

            var outfitMap = {
                '日常': 'rc',
                '外出': 'wc',
                '战斗': 'zf',
                '制服': 'zf'
            };

            window.cardStates = {};

            /* ========== 智能路由获取基础链接 ========== */
            function getBaseUrl(charCode) {
                return (window.RT_IMG_BASE || 'https://testingcf.jsdelivr.net/gh/TakaoTay/art@main/');
            }

            function getImageUrl(charCode, outfitCode, index) {
                return getBaseUrl(charCode) + charCode + '_' + outfitCode + '_' + index + '.png';
            }

            /* ========== 数据解析引擎 ========== */
            function parseSceneData(text) {
                var result = { type: '日常场景', characters: [] };
                var match = text.match(/<SceneInfo>([\s\S]*?)<\/SceneInfo>/);
                if (!match || !match[1]) return null;

                var lines = match[1].split('\n');
                lines.forEach(function(line) {
                    line = line.trim();
                    if (!line) return;

                    if (line.indexOf('场景类型：') !== -1) {
                        result.type = line.replace('场景类型：', '').replace('场景类型:', '').trim();
                    }

                    if (line.startsWith('-')) {
                        var parts = line.substring(1).split('|');
                        if (parts.length >= 2) {
                            var parsedName = parts[0].trim();
                            if (nameMap.hasOwnProperty(parsedName)) {
                                var charData = nameMap[parsedName];
                                result.characters.push({
                                    name: charData.displayName, /* 统一显示为全名 */
                                    code: charData.code,
                                    outfit: parts[1].trim()
                                });
                            }
                        }
                    }
                });
                return result;
            }

            /* ========== SVG 图标 ========== */
            var svgs = {
                noImage: '<svg viewBox="0 0 24 24"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg>',
                arrowDown: '<svg viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>',
                gallery: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M4 8h4V4H4v4zm6 12h4v-4h-4v4zm-6 0h4v-4H4v4zm0-6h4v-4H4v4zm6 0h4v-4h-4v4zm6-10v4h4V4h-4zm-6 4h4V4h-4v4zm6 6h4v-4h-4v4zm0 6h4v-4h-4v4z"/></svg>',
                left: '<svg viewBox="0 0 24 24"><path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/></svg>',
                right: '<svg viewBox="0 0 24 24"><path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6-1.41-1.41z"/></svg>'
            };

            /* ========== 图库界面生成 (增加 lazy loading) ========== */
            function buildGalleryModalHtml() {
                var html = '<div class="modal-overlay gallery-modal" id="gallery-modal">';
                html += '<div class="gallery-modal-header">';
                html += '  <div class="gallery-modal-title">' + svgs.gallery + '&nbsp;<span>✦ 画廊 ✦</span></div>';
                html += '  <div class="gallery-modal-close" onclick="window.closeGalleryModal()">关闭</div>';
                html += '</div>';

                html += '<div class="gallery-modal-content" onclick="event.stopPropagation()">'; /* 阻止点击内容区域关闭 */
                /* 过滤重复名字防止图库中展示重复的记录，这里我们基于 code 去重生成 */
                var addedCodes = {};
                allCharacters.forEach(function(char) {
                    if (addedCodes[char.code]) return;
                    addedCodes[char.code] = true;

                    html += '<div class="gallery-section">';
                    html += '<div class="gallery-section-title">❀ 档案记录：' + char.name + '</div>';

                    outfitTypes.forEach(function(outfit) {
                        html += '<div class="gallery-outfit-group">';
                        html += '<div class="gallery-row">';
                        for(var i = 1; i <= 5; i++) {
                            var imgUrl = getImageUrl(char.code, outfit.code, i);
                            html += '<div class="gallery-thumb" onclick="window.openImageModal(\'' + imgUrl + '\')">';
                            /* 性能优化：加入 loading="lazy" */
                            html += '  <img src="' + imgUrl + '" loading="lazy" alt="' + char.name + ' ' + outfit.label + ' ' + i + '" onerror="this.parentElement.style.display=\'none\'">';
                            html += '  <div class="gallery-thumb-label">' + outfit.label + ' ' + i + '</div>';
                            html += '</div>';
                        }
                        html += '</div>';
                        html += '</div>';
                    });

                    html += '</div>';
                });
                html += '</div></div>';
                return html;
            }

            /* ========== 主界面渲染 ========== */
            function init() {
                try {
                    var root = document.getElementById('app-root');
                    var text = getMessageData();
                    if (!text) {
                        root.innerHTML = '<div class="scene-info-panel"><div class="system-loading">呜...没有读取到场景数据呢</div></div>';
                        return;
                    }

                    var data = parseSceneData(text);
                    if (!data || data.characters.length === 0) {
                        root.style.display = 'none';
                        return;
                    }

                    var html = '<div class="scene-info-panel">';
                    html += '<div class="scene-header">';
                    html += '  <div class="meta-row"><span class="meta-star">✧</span><span>' + data.type + '</span><span class="meta-star">✧</span></div>';
                    html += '  <div class="controls-container">';
                    html += '    <button class="action-button" id="btn-collapse">';
                    html += '      <div class="collapse-icon" id="icon-collapse">' + svgs.arrowDown + '</div>';
                    html += '      <span id="text-collapse">折叠卡片</span>';
                    html += '    </button>';
                    html += '    <button class="action-button" id="btn-gallery">';
                    html += '      <div class="collapse-icon">' + svgs.gallery + '</div>';
                    html += '      <span>打开图库</span>';
                    html += '    </button>';
                    html += '  </div>';
                    html += '</div>';

                    html += '<div class="character-container" id="char-container">';
                    html += '<div class="character-grid">';

                    data.characters.forEach(function(char, idx) {
                        var codeName = char.code;
                        var codeOutfit = outfitMap[char.outfit] || 'rc';
                        var cardId = 'card_' + idx;

                        var randomStart = Math.floor(Math.random() * 5) + 1;
                        window.cardStates[cardId] = { charCode: codeName, outfitCode: codeOutfit, index: randomStart };
                        var imgSrc = getImageUrl(codeName, codeOutfit, randomStart);

                        var fallbackHtml = '<div class="character-avatar-fallback" id="fb_' + cardId + '" style="display:none;">' + svgs.noImage + '<span>加载失败惹</span></div>';
                        var errorEvent = "this.style.opacity=\'0\'; document.getElementById(\'fb_" + cardId + "\').style.display=\'flex\';";

                        html += '<div class="character-card">';

                        html += '  <div class="character-avatar" onclick="window.openImageModal(document.getElementById(\'img_' + cardId + '\').src)">';
                        /* 首页立绘也加入懒加载，避免首屏拥堵 */
                        html += '    <img id="img_' + cardId + '" src="' + imgSrc + '" loading="lazy" alt="' + char.name + '" onerror="' + errorEvent + '">';
                        html +=      fallbackHtml;
                        html += '  </div>';

                        html += '  <div class="character-info-area">';
                        html += '    <div class="character-name-group">';
                        html += '      <div class="character-name">' + char.name + '</div>';
                        html += '      <div class="character-outfit">' + char.outfit + '</div>';
                        html += '    </div>';

                        html += '    <div class="switcher-controls">';
                        html += '      <div class="switch-btn" onclick="window.changeCardImage(event, \'' + cardId + '\', -1)">' + svgs.left + '</div>';
                        html += '      <div class="switch-index" id="idx_' + cardId + '">' + randomStart + ' / 5</div>';
                        html += '      <div class="switch-btn" onclick="window.changeCardImage(event, \'' + cardId + '\', 1)">' + svgs.right + '</div>';
                        html += '    </div>';

                        html += '  </div>';
                        html += '</div>';
                    });

                    html += '</div></div></div>';

                    /* 追加 Modals */
                    html += buildGalleryModalHtml();
                    html += '<div id="image-modal" class="modal-overlay image-viewer-modal" onclick="window.closeImageModal()">';
                    html += '  <img id="modal-img" src="" alt="立绘大图" onclick="event.stopPropagation()">';
                    html += '</div>';

                    root.innerHTML = html;

                    setTimeout(function() {
                        var container = document.getElementById('char-container');
                        var icon = document.getElementById('icon-collapse');
                        var collapseText = document.getElementById('text-collapse');
                        var btnCollapse = document.getElementById('btn-collapse');
                        if (btnCollapse) {
                            btnCollapse.onclick = function() {
                                container.classList.toggle('collapsed');
                                icon.classList.toggle('collapsed');
                                collapseText.textContent = container.classList.contains('collapsed') ? '展开卡片' : '折叠卡片';
                            };
                        }

                        var btnGallery = document.getElementById('btn-gallery');
                        if (btnGallery) {
                            btnGallery.onclick = function() {
                                var modal = document.getElementById('gallery-modal');
                                if (modal) {
                                    modal.classList.add('show');
                                    window.lockBodyScroll(true);
                                }
                            };
                        }
                    }, 50);
                } catch (error) {
                    console.error("渲染错误:", error);
                }
            }

            /* ========== 辅助：防滚动穿透 ========== */
            var scrollPosition = 0;
            window.lockBodyScroll = function(isLock) {
                var body = document.body;
                if (isLock) {
                    scrollPosition = window.pageYOffset || document.documentElement.scrollTop;
                    body.style.position = 'fixed';
                    body.style.top = '-' + scrollPosition + 'px';
                    body.style.width = '100%';
                } else {
                    body.style.position = '';
                    body.style.top = '';
                    body.style.width = '';
                    window.scrollTo(0, scrollPosition);
                }
            };

            /* ========== 全局交互逻辑 ========== */
            /* 简易防抖，防止狂点导致资源过度请求 */
            var switchLocks = {};

            window.changeCardImage = function(event, cardId, delta) {
                if (event) event.stopPropagation();

                if (switchLocks[cardId]) return;
                switchLocks[cardId] = true;
                setTimeout(function() { switchLocks[cardId] = false; }, 300);

                var state = window.cardStates[cardId];
                if (!state) return;

                state.index += delta;
                if (state.index > 5) state.index = 1;
                if (state.index < 1) state.index = 5;

                var newSrc = getImageUrl(state.charCode, state.outfitCode, state.index);

                var imgElem = document.getElementById('img_' + cardId);
                var idxElem = document.getElementById('idx_' + cardId);
                var fbElem = document.getElementById('fb_' + cardId);

                /* 平滑过渡效果 */
                if(imgElem) imgElem.style.opacity = '0.3';

                var tempImg = new Image();
                tempImg.onload = function() {
                    if (imgElem) {
                        imgElem.src = newSrc;
                        imgElem.style.opacity = '1';
                    }
                    if (fbElem) fbElem.style.display = 'none';
                };
                tempImg.onerror = function() {
                    if (imgElem) imgElem.style.opacity = '0';
                    if (fbElem) fbElem.style.display = 'flex';
                };
                tempImg.src = newSrc;

                if (idxElem) idxElem.textContent = state.index + ' / 5';
            };

            window.openImageModal = function(src) {
                var modal = document.getElementById('image-modal');
                var img = document.getElementById('modal-img');
                if (modal && img && src.indexOf('.png') !== -1) {
                    img.src = src;
                    modal.classList.add('show');
                    window.lockBodyScroll(true);
                }
            };
            window.closeImageModal = function() {
                var modal = document.getElementById('image-modal');
                if (modal) {
                    modal.classList.remove('show');
                    /* 延迟移除防穿透，避免页面闪动 */
                    setTimeout(function() { window.lockBodyScroll(false); }, 300);
                }
            };
            window.closeGalleryModal = function() {
                var modal = document.getElementById('gallery-modal');
                if (modal) {
                    modal.classList.remove('show');
                    setTimeout(function() { window.lockBodyScroll(false); }, 300);
                }
            };

            /* 修正后的酒馆规范加载方式 */
            $(function() {
                init();
            });
        })();
    </script>
</body>
</html>
