        @keyframes gridItemPop { to { opacity: 1; transform: translateY(0); } }
        .gallery-item:hover { transform: translateY(-4px); box-shadow: 0 8px 20px rgba(212,168,154,0.25); border-color: #d4a89a; }
        .gallery-item img { width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity 0.5s; }
        .gallery-item img.loaded { opacity: 1; }
        .gallery-item .img-label { position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(transparent, rgba(0,0,0,0.7)); color: #fff; padding: 15px 12px 8px; font-size: 11px; font-family: "SF Mono", Consolas, monospace; opacity: 0; transition: opacity 0.3s; }
        .gallery-item:hover .img-label { opacity: 1; }
