        /* ================= 核心手机端响应式适配 (利用 aspect-ratio 实现流式) ================= */

        /* 平板端过渡 (小于 1024px) */
        @media screen and (max-width: 1024px) {
            .novel-container {
                aspect-ratio: 16 / 10;
                margin-left: 0;
            }
            .nav-panel { width: 30%; min-width: 180px; }
            .stage { width: 70%; }
            .char-name { font-size: clamp(24px, 3.5vw, 36px); }
            .jump-btn { padding: 10px 20px; font-size: 11px; }
