            .novel-obi { width: 35px; }
            .obi-text { font-size: 11px; }
        }

        /* 标准手机端 (小于 768px) */
        @media screen and (max-width: 768px) {
            .artbook-wrapper { padding: 5px; }
            .novel-obi { display: none; } /* 隐藏腰封，留出横向空间 */
            .bookmark-ribbon { transform: scale(0.7); top: 0; right: 10px; transform-origin: top center; }

            .novel-container {
                flex-direction: column; /* 改为上下堆叠布局 */
                aspect-ratio: 9 / 15.5; /* 纵向黄金长条比例 */
                height: auto;
                min-height: 550px;
                border-radius: 12px;
            }

            /* 左侧导航变顶部横滑标签 */
            .nav-panel {
                width: 100%;
                flex-shrink: 0;
                border-right: none;
                border-bottom: 2px dashed rgba(0,0,0,0.08);
                padding-bottom: 5px;
                z-index: 105;
            }
            .nav-header { padding: 4% 5% 2%; }
            .nav-title { font-size: clamp(18px, 4vw, 22px); }
            .nav-title::after { width: 40px; bottom: -5px; }
            .nav-subtitle { font-size: 9px; margin-top: 5px; }

            .nav-list {
                display: flex; flex-direction: row;
                overflow-x: auto; overflow-y: hidden;
                padding: 10px 15px;
            }

            .nav-item {
                flex: 0 0 130px; /* 固定宽度，允许横滑 */
                margin-bottom: 0; margin-right: 12px;
                padding: 10px; border-radius: 8px;
            }
            .nav-item.active {
                border: 2px solid transparent;
                border-bottom: 3px solid var(--accent-color, #ff758c);
                box-shadow: 0 8px 15px rgba(0,0,0,0.05);
                transform: scale(1.02);
            }
            .nav-item.active::before { display: none; } /* 隐藏左侧选中三角 */

            /* 主舞台撑满剩余空间 */
            .stage { width: 100%; flex-grow: 1; }

            /* 主题层改为上下排版 */
            .theme-layer { flex-direction: column; }
            .bg-watermark { font-size: clamp(60px, 18vw, 90px); top: 5%; opacity: 0.6; }

            /* 上半部分：情报文字区缩紧 */
            .info-panel {
                width: 100%; height: 50%;
                padding: 4% 6% 0 6%;
                transform: translateY(5px);
            }

            .chapter-badge { margin-bottom: 2%; }
            .char-name { font-size: clamp(24px, 7vw, 32px); }
            .char-romaji { font-size: 9px; margin-bottom: 3%; }
            .char-quote { font-size: clamp(11px, 3.5vw, 13px); margin-bottom: 3%; }
            .tags-container { margin-bottom: 3%; gap: 6px; }
            .char-tag { padding: 4px 8px; font-size: 9px; }
            .char-desc { font-size: clamp(11px, 3vw, 12px); margin-bottom: 4%; line-height: 1.6; padding: 10px 12px; }
            .jump-btn { padding: 8px 20px; font-size: 11px; }
            .jump-btn::after { display: none; } /* 手机端关闭扫光动画以节省性能 */

            /* 下半部分：相框区 */
            .frame-panel {
                width: 100%; height: 50%;
                padding: 2%;
                transform: translateY(0) translateX(0);
            }
            .theme-layer.active .frame-panel { transform: translateY(0) translateX(0); }

            .photo-wrapper { width: 85%; height: 85%; }
            .obj-stamp { width: 35%; max-width: 140px; bottom: 10%; right: 5%; }

            .floating-deco { transform: scale(0.7); }
        }

        /* 极小屏幕手机 (例如 iPhone SE 等 480px 以下屏幕) */
        @media screen and (max-width: 480px) {
            .novel-container {
                aspect-ratio: 9 / 17; /* 更为细长的纵向空间 */
                min-height: 500px;
            }
            .nav-item { flex: 0 0 110px; padding: 8px; }
            .nav-name span { font-size: 12px; }
            .nav-no { font-size: 9px; }

            .info-panel { padding: 3% 5% 0 5%; }
            .char-desc { padding: 8px; line-height: 1.5; margin-bottom: 4%; }
            .tags-container { gap: 4px; }

            /* 相框进一步调校内边距防止挤压 */
            .variant-yuunagi { padding: 2% 2% 10% 2%; }
            .variant-rin { padding: 2%; outline-offset: 4px; border-width: 3px; }
            .variant-sumire { padding: 4%; border-width: 6px; }
            .variant-reina { padding: 2%; }
            .variant-shizuku { padding: 0 2% 2% 2%; }
            .variant-chinatsu { padding: 2% 2% 8% 2%; }
            .variant-rei { padding: 1%; }
            .variant-yui { padding: 3%; border-radius: 16px; }

            .fastener-sumire { width: 25%; font-size: 16px; }
        }

